import pandas as pd
import numpy as np
from datetime import datetime

def transform(df):
    def fetch_weather(date_time):
        dt = datetime.strptime(date_time, '%Y-%m-%d %H:%M:%S')
        if dt.hour >= 6 and dt.hour < 12:
            return {'temperature': 15, 'weather_condition': 'Morning'}
        elif dt.hour >= 12 and dt.hour < 18:
            return {'temperature': 25, 'weather_condition': 'Afternoon'}
        else:
            return {'temperature': 10, 'weather_condition': 'Night'}

    df['weather'] = df.apply(lambda row: fetch_weather(row['tpep_pickup_datetime']), axis=1)
    return df
